package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.AuthResponse; import com.pranit.productsupport.contracts.LoginRequest; import com.pranit.productsupport.contracts.RegisterRequest; import com.pranit.productsupport.core.domain.AppUser; import com.pranit.productsupport.core.domain.UserRole; import com.pranit.productsupport.core.repository.AppUserRepository; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.List; import java.util.Locale; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jose.jws.JwsHeader; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.JwtClaimsSet; import org.springframework.security.oauth2.jwt.JwtEncoder; import org.springframework.security.oauth2.jwt.JwtEncoderParameters; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {
 private final AppUserRepository users; private final PasswordEncoder passwords=new BCryptPasswordEncoder(12); private final JwtEncoder encoder; private final String issuer; private final long ttl;
 public AuthService(AppUserRepository users,JwtEncoder encoder,@Value("${app.security.jwt-issuer}") String issuer,@Value("${app.security.jwt-ttl-minutes}") long ttl){this.users=users;this.encoder=encoder;this.issuer=issuer;this.ttl=ttl;}
 @Transactional public AuthResponse register(RegisterRequest r){String email=normalize(r.email());if(users.existsByEmail(email))throw ApiException.conflict("An account with this email already exists");AppUser user=users.save(new AppUser(r.fullName().trim(),email,passwords.encode(r.password()),UserRole.CUSTOMER));return token(user);}
 @Transactional(readOnly=true) public AuthResponse login(LoginRequest r){AppUser u=users.findByEmail(normalize(r.email())).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!u.isActive()||!passwords.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return token(u);}
 private AuthResponse token(AppUser u){Instant now=Instant.now();JwtClaimsSet claims=JwtClaimsSet.builder().issuer(issuer).issuedAt(now).expiresAt(now.plus(ttl,ChronoUnit.MINUTES)).subject(u.getId().toString()).claim("email",u.getEmail()).claim("roles",List.of("ROLE_"+u.getRole().name())).build();String encoded=encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();return new AuthResponse(encoded,"Bearer",ttl*60,u.getId(),u.getEmail(),u.getRole().name());}
 private String normalize(String email){return email.trim().toLowerCase(Locale.ROOT);}
}
